<?php require_once __DIR__.'/functions.php';layout_header('Import');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$new=json_decode(file_get_contents($_FILES['json']['tmp_name']??''),true,512,JSON_THROW_ON_ERROR);if(!isset($new['words']))$new=['version'=>'imported','total_unique'=>count($new),'levels'=>[],'words'=>$new];if(!is_array($new['words']))throw new RuntimeException('Missing words array');$msg='Valid JSON. Words found: '.count($new['words']);if(isset($_POST['replace'])){save_db($new);$msg='Database replaced successfully.';}}catch(Throwable $e){$msg='Import failed: '.$e->getMessage();}}?><div class="panel"><h2>Import JSON</h2><?php if($msg):?><div class="alert alert-info"><?=h($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="file" name="json" accept=".json,application/json" class="form-control" required><label class="form-check mt-3"><input type="checkbox" name="replace" class="form-check-input"> Replace Database</label><button class="btn btn-primary mt-3">Validate / Import</button></form></div><?php layout_footer();?>